style.css:
/* BLACKOUT — Minimal Studio */
 /* i really want this to be global */

/* swap these values to change the palette */
:root {
    --my-bg: #050505;
    --my-surface: #101010;
    --my-text: #e8e8e8;
    --my-muted: #777777;
    --my-accent: #ffffff;
    --my-border: #252525;
    --my-font: "Berlin Sans FB", Arial, sans-serif;
}

/* dark minimal background */
html,
body {
    background: var(--my-bg) !important;
    color: var(--my-text) !important;
    font-family: var(--my-font) !important;
}

/* clean typography */
h1, h2, h3, h4, h5, h6 {
    font-family: var(--my-font) !important;
    color: var(--my-accent) !important;
    font-weight: 900 !important;
    letter-spacing: -1.5px !important;
}

/* minimal paragraphs */
p, li, label, span {
    font-family: var(--my-font) !important;
}

/* clean links */
a {
    color: var(--my-text) !important;
    text-decoration-color: var(--my-muted) !important;
    transition: color 0.2s ease !important;
}

a:hover {
    color: #999999 !important;
}

/* subtle borders */
hr,
input,
textarea,
select {
    border-color: var(--my-border) !important;
}

/* dark form elements */
input,
textarea,
select {
    background: var(--my-surface) !important;
    color: var(--my-text) !important;
    border-radius: 3px !important;
}

/* minimal buttons */
button {
    background: var(--my-surface) !important;
    color: var(--my-text) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 3px !important;
    font-family: var(--my-font) !important;
    transition: 0.2s ease !important;
}

button:hover {
    background: #252525 !important;
}

/* subtle image corners */
img {
    border-radius: 2px !important;
}

/* scrollbar */
::-webkit-scrollbar {
    width: 6px !important;
}

::-webkit-scrollbar-track {
    background: var(--my-bg) !important;
}

::-webkit-scrollbar-thumb {
    background: #444444 !important;
    border-radius: 10px !important;
}
